import { useId, useState } from "react"
import { toast } from "sonner"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { useCollection } from "@/lib/mini/store"

import { WorkspacePanes } from "./workspace-panes"
import type { WorkspaceLayout } from "./types"

type Recipe = {
  id: string
  title: string
  servings: number
  ingredients: string[]
  steps: string[]
  created: string
  modified: string
}

type Preview = "live" | "empty" | "loading" | "error"

const LAYOUT_STORE = "workspace-panes-layout"

function recipe(
  id: string,
  title: string,
  servings: number,
  ingredients: string[],
  steps: string[]
): Recipe {
  return {
    id,
    title,
    servings,
    ingredients,
    steps,
    created: "2026-09-02T10:15:00.000Z",
    modified: "2026-10-12T18:40:00.000Z",
  }
}

const seed: Recipe[] = [
  recipe("r-pancakes", "Lemon ricotta pancakes", 4, ["1 cup ricotta", "3 eggs", "3/4 cup flour", "Zest of 1 lemon", "Butter for the pan"], ["Whisk ricotta, eggs and zest.", "Fold in the flour until just combined.", "Cook in butter, about 2 minutes a side."]),
  recipe("r-shakshuka", "Shakshuka", 3, ["1 onion, sliced", "2 peppers, sliced", "1 can crushed tomatoes", "6 eggs", "1 tsp cumin", "1 tsp paprika"], ["Soften the onion and peppers in oil.", "Add spices and tomatoes; simmer 10 minutes.", "Make wells, crack in the eggs, cover until set."]),
  recipe("r-ribs", "Slow-braised short ribs with red wine, shallots, thyme, orange peel and a very long overnight rest before serving", 6, ["2 kg short ribs", "1 bottle red wine", "8 shallots", "Thyme", "1 strip orange peel"], ["Season and sear the ribs.", "Add wine, shallots, thyme and peel.", "Braise at 150 C for 3 hours.", "Rest overnight in the liquid, reheat to serve."]),
  recipe("r-dal", "Red lentil dal", 4, ["1 cup red lentils", "1 onion", "3 garlic cloves", "1 tbsp grated ginger", "1 tsp turmeric", "1 can coconut milk"], ["Sweat onion, garlic and ginger.", "Add lentils, turmeric and 3 cups water.", "Simmer 20 minutes, stir in coconut milk."]),
  recipe("r-focaccia", "Overnight focaccia", 8, ["500 g bread flour", "400 g water", "10 g salt", "2 g yeast", "Olive oil", "Flaky salt"], ["Mix everything except the oil; rest 12 hours.", "Stretch into an oiled tray and dimple.", "Bake at 230 C for 22 minutes."]),
  recipe("r-gazpacho", "Tomato gazpacho", 4, ["1 kg ripe tomatoes", "1 cucumber", "1 pepper", "1 garlic clove", "3 tbsp sherry vinegar", "Olive oil"], ["Blend the vegetables with garlic and vinegar.", "Stream in oil while blending.", "Chill for 2 hours."]),
  recipe("r-tacos", "Crispy fish tacos", 4, ["500 g white fish", "Corn tortillas", "1/4 red cabbage", "2 limes", "Hot sauce", "Mayonnaise"], ["Dredge the fish in seasoned flour and fry.", "Toss the cabbage with lime.", "Fill warm tortillas, finish with sauce."]),
  recipe("r-risotto", "Mushroom risotto", 4, ["300 g arborio rice", "400 g mushrooms", "1 L stock", "1 shallot", "Parmesan", "White wine"], ["Brown the mushrooms and set aside.", "Toast rice with the shallot, add wine.", "Add stock a ladle at a time, 18 minutes.", "Fold in mushrooms and cheese."]),
  recipe("r-granola", "Maple granola", 10, ["4 cups rolled oats", "1 cup nuts", "1/2 cup maple syrup", "1/3 cup oil", "1 tsp cinnamon"], ["Mix everything in a bowl.", "Spread on a tray and bake at 160 C, stirring twice.", "Cool completely before storing."]),
  recipe("r-salmon", "Miso-glazed salmon", 2, ["2 salmon fillets", "2 tbsp white miso", "1 tbsp mirin", "1 tsp soy sauce"], ["Mix miso, mirin and soy.", "Coat the fillets and rest 20 minutes.", "Broil for 8 minutes."]),
  recipe("r-brownies", "Fudgy brownies", 12, ["200 g dark chocolate", "150 g butter", "200 g sugar", "3 eggs", "80 g flour"], ["Melt chocolate and butter together.", "Whisk in sugar, then eggs, then flour.", "Bake at 175 C for 25 minutes."]),
  recipe("r-slaw", "Crunchy peanut slaw", 6, ["1/2 green cabbage", "2 carrots", "1/4 cup peanut butter", "2 tbsp lime juice", "1 tbsp soy sauce"], ["Shred the vegetables.", "Whisk the dressing.", "Toss just before serving."]),
]

const demoLayout: WorkspaceLayout = {
  id: "layout",
  activeGroupId: "g-left",
  sidebarOpen: true,
  recent: ["r-shakshuka", "r-pancakes"],
  groups: [
    {
      groupId: "g-left",
      activeTabId: "t-left-1",
      tabs: [
        { tabId: "t-left-1", itemId: "r-pancakes", mode: "structured" },
        { tabId: "t-left-2", itemId: "r-shakshuka", mode: "structured" },
      ],
    },
    {
      groupId: "g-right",
      activeTabId: "t-right-1",
      tabs: [{ tabId: "t-right-1", itemId: "r-pancakes", mode: "raw" }],
    },
  ],
}

function toRaw(r: Recipe): string {
  return [
    "---",
    `title: ${r.title}`,
    `servings: ${r.servings}`,
    "---",
    "",
    "## Ingredients",
    "",
    ...r.ingredients.map((line) => `- ${line}`),
    "",
    "## Steps",
    "",
    ...r.steps.map((line, i) => `${i + 1}. ${line}`),
    "",
  ].join("\n")
}

function parseRaw(raw: string, current: Recipe): Recipe {
  const lines = raw.replace(/\r\n/g, "\n").split("\n")
  if (lines[0]?.trim() !== "---") throw new Error('The file must start with a "---" line.')
  const end = lines.findIndex((line, i) => i > 0 && line.trim() === "---")
  if (end === -1) throw new Error('The front matter is missing its closing "---" line.')

  const fields = new Map<string, string>()
  for (const line of lines.slice(1, end)) {
    const match = /^(\w+):\s*(.*)$/.exec(line)
    if (match) fields.set(match[1], match[2])
  }
  const title = fields.get("title")?.trim()
  if (!title) throw new Error("The front matter needs a title.")
  const servings = Number(fields.get("servings"))
  if (!Number.isInteger(servings) || servings < 1) {
    throw new Error("servings must be a whole number, 1 or more.")
  }

  const ingredients: string[] = []
  const steps: string[] = []
  let section: "ingredients" | "steps" | undefined
  const seen = new Set<string>()
  for (const line of lines.slice(end + 1)) {
    const heading = /^##\s+(.*)$/.exec(line)
    if (heading) {
      const name = heading[1].trim().toLowerCase()
      section = name === "ingredients" ? "ingredients" : name === "steps" ? "steps" : undefined
      if (section) seen.add(section)
      continue
    }
    const bullet = /^-\s+(.*\S)\s*$/.exec(line)
    const numbered = /^\d+\.\s+(.*\S)\s*$/.exec(line)
    if (section === "ingredients" && bullet) ingredients.push(bullet[1])
    if (section === "steps" && numbered) steps.push(numbered[1])
  }
  if (!seen.has("ingredients")) throw new Error('Add an "## Ingredients" section.')
  if (!seen.has("steps")) throw new Error('Add a "## Steps" section.')

  return { ...current, title, servings, ingredients, steps }
}

function DraftField({
  label,
  value,
  onCommit,
  multiline,
}: {
  label: string
  value: string
  onCommit: (next: string) => void
  multiline?: boolean
}) {
  const id = useId()
  const [draft, setDraft] = useState(value)
  const [seen, setSeen] = useState(value)
  if (value !== seen) {
    setSeen(value)
    setDraft(value)
  }
  const commit = () => {
    if (draft !== value) onCommit(draft)
  }
  return (
    <div className="flex flex-col gap-1">
      <label htmlFor={id} className="text-xs font-medium text-muted-foreground">
        {label}
      </label>
      {multiline ? (
        <Textarea
          id={id}
          rows={Math.max(3, draft.split("\n").length)}
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          onBlur={commit}
          className="text-sm"
        />
      ) : (
        <Input
          id={id}
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          onBlur={commit}
          className="text-sm"
        />
      )}
    </div>
  )
}

const lines = (text: string) => text.split("\n").map((line) => line.trim()).filter(Boolean)

function RecipeForm({
  recipe: r,
  update,
  onDelete,
}: {
  recipe: Recipe
  update: (patch: Partial<Recipe>) => Promise<void>
  onDelete: () => void
}) {
  const save = (patch: Partial<Recipe>) => void update(patch).catch(() => undefined)
  return (
    <div className="flex flex-col gap-4">
      <DraftField
        label="Title"
        value={r.title}
        onCommit={(title) => save({ title: title.trim() || r.title })}
      />
      <DraftField
        label="Servings"
        value={String(r.servings)}
        onCommit={(next) => {
          const servings = Number(next)
          if (Number.isInteger(servings) && servings > 0) save({ servings })
        }}
      />
      <DraftField
        multiline
        label="Ingredients (one per line)"
        value={r.ingredients.join("\n")}
        onCommit={(next) => save({ ingredients: lines(next) })}
      />
      <DraftField
        multiline
        label="Steps (one per line)"
        value={r.steps.join("\n")}
        onCommit={(next) => save({ steps: lines(next) })}
      />
      <div>
        <Button variant="outline" size="sm" onClick={onDelete}>
          Delete recipe
        </Button>
      </div>
    </div>
  )
}

const formatDate = (iso: string) => new Date(iso).toLocaleDateString()

export default function Demo() {
  useCollection<WorkspaceLayout>(LAYOUT_STORE, [demoLayout])
  const recipes = useCollection<Recipe>("workspace-panes-demo", seed)
  const [preview, setPreview] = useState<Preview>("live")

  async function onChange(next: Recipe) {
    try {
      await recipes.update(next.id, { ...next, modified: new Date().toISOString() })
    } catch (cause) {
      toast.error(cause instanceof Error ? cause.message : "Could not save the recipe")
      throw cause
    }
  }

  async function onCreate() {
    const now = new Date().toISOString()
    const id = crypto.randomUUID()
    await recipes.add({
      id,
      title: "Untitled recipe",
      servings: 2,
      ingredients: [],
      steps: [],
      created: now,
      modified: now,
    })
    setPreview("live")
    return id
  }

  const status = preview === "loading" ? "loading" : preview === "error" ? "error" : recipes.status
  const items = preview === "empty" ? [] : recipes.items

  return (
    <div className="flex h-full min-h-[32rem] flex-col">
      <div className="flex shrink-0 items-center gap-2 border-b px-3 py-1.5">
        <span id="workspace-panes-preview" className="text-xs text-muted-foreground">
          Preview state
        </span>
        <ToggleGroup
          type="single"
          variant="outline"
          size="sm"
          spacing={0}
          aria-labelledby="workspace-panes-preview"
          value={preview}
          onValueChange={(value) => {
            if (value) setPreview(value as Preview)
          }}
        >
          {(["live", "empty", "loading", "error"] as const).map((name) => (
            <ToggleGroupItem key={name} value={name} className="h-6 px-2 text-xs capitalize">
              {name}
            </ToggleGroupItem>
          ))}
        </ToggleGroup>
      </div>
      <div className="min-h-0 flex-1">
        <WorkspacePanes
          items={items}
          status={status}
          error={preview === "error" ? new Error("The recipe store could not be read (simulated).") : recipes.error}
          onRetry={() => setPreview("live")}
          renderStructured={(r, { update }) => (
            <RecipeForm recipe={r} update={update} onDelete={() => void recipes.remove(r.id)} />
          )}
          toRaw={toRaw}
          parseRaw={parseRaw}
          onChange={onChange}
          onCreate={onCreate}
          badge={() => "MD"}
          tooltip={(r) => `Created ${formatDate(r.created)}, modified ${formatDate(r.modified)}`}
        />
      </div>
    </div>
  )
}

import { useState } from "react"

import { Kbd } from "@/components/ui/kbd"

type EmptyPaneProps = {
  hasItems: boolean
  recent: { id: string; title: string }[]
  onCreate?: () => void
  onGoTo: () => void
  onOpen: (id: string) => void
  onClose: () => void
}

const linkClass =
  "text-sm text-primary underline-offset-2 outline-none hover:underline focus-visible:underline focus-visible:ring-2 focus-visible:ring-ring rounded-sm"

function Link({ label, keys, ...rest }: { label: string; keys?: string } & React.ComponentProps<"button">) {
  return (
    <li className="flex items-center gap-2">
      <button type="button" data-empty-link className={linkClass} {...rest}>
        {label}
      </button>
      {keys ? <Kbd>{keys}</Kbd> : null}
    </li>
  )
}

/** What a tab with no record shows: plain text links with their shortcuts. */
export function EmptyPane({ hasItems, recent, onCreate, onGoTo, onOpen, onClose }: EmptyPaneProps) {
  const [showRecent, setShowRecent] = useState(false)
  return (
    <div className="flex h-full flex-col items-center justify-center gap-3 p-6">
      <ul className="flex flex-col items-start gap-2">
        {onCreate ? <Link label="Create new item" keys="Alt+N" onClick={onCreate} /> : null}
        {hasItems ? (
          <>
            <Link label="Go to item" keys="Alt+O" onClick={onGoTo} />
            <Link
              label="See recent items"
              aria-expanded={showRecent}
              onClick={() => setShowRecent((open) => !open)}
            />
            <Link label="Close" onClick={onClose} />
          </>
        ) : null}
      </ul>
      {!onCreate && !hasItems ? (
        <p className="text-sm text-muted-foreground">Nothing to open yet.</p>
      ) : null}
      {showRecent ? (
        recent.length > 0 ? (
          <ul aria-label="Recent items" className="flex flex-col items-start gap-1">
            {recent.map((item) => (
              <li key={item.id}>
                <button type="button" className={linkClass} onClick={() => onOpen(item.id)}>
                  {item.title}
                </button>
              </li>
            ))}
          </ul>
        ) : (
          <p className="text-xs text-muted-foreground">No recent items.</p>
        )
      ) : null}
    </div>
  )
}

import { ScrollArea } from "@/components/ui/scroll-area"
import { Badge } from "@/components/ui/badge"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

import type { OpenHow, WorkspaceItem } from "./types"

type ItemListProps<T extends WorkspaceItem> = {
  items: T[]
  activeId?: string
  onOpen: (id: string, how: OpenHow) => void
  badge?: (item: T) => string | undefined
  tooltip?: (item: T) => string | undefined
}

function howOf(event: React.MouseEvent): OpenHow {
  if (event.metaKey || event.ctrlKey) return event.altKey ? "split" : "tab"
  return "here"
}

function Row<T extends WorkspaceItem>({
  item,
  active,
  onOpen,
  badge,
  tooltip,
}: Omit<ItemListProps<T>, "items" | "activeId"> & { item: T; active: boolean }) {
  const hover = tooltip?.(item)
  const label = badge?.(item)
  const row = (
    <button
      type="button"
      aria-current={active ? "true" : undefined}
      onClick={(event) => onOpen(item.id, howOf(event))}
      className={cn(
        "flex w-full items-center gap-2 rounded-md border border-transparent px-2 py-1 text-left text-xs outline-none hover:border-border focus-visible:ring-2 focus-visible:ring-ring",
        active && "bg-sidebar-accent font-medium"
      )}
    >
      <span className="min-w-0 flex-1 truncate" title={hover ? undefined : item.title}>
        {item.title}
      </span>
      {label ? (
        <Badge variant="secondary" className="h-4 shrink-0 px-1.5 text-[10px]">
          {label}
        </Badge>
      ) : null}
    </button>
  )
  if (!hover) return row
  return (
    <Tooltip delayDuration={700}>
      <TooltipTrigger asChild>{row}</TooltipTrigger>
      <TooltipContent side="right" className="flex-col items-start gap-0.5">
        <span className="font-medium">{item.title}</span>
        <span>{hover}</span>
      </TooltipContent>
    </Tooltip>
  )
}

/** One plain row per record; click opens here, Mod-click in a new tab, Mod+Alt-click in a new group. */
export function ItemList<T extends WorkspaceItem>({
  items,
  activeId,
  onOpen,
  badge,
  tooltip,
}: ItemListProps<T>) {
  return (
    <ScrollArea className="min-h-0 flex-1 [&_[data-slot=scroll-area-viewport]>div]:!block">
      <ul aria-label="Items" className="flex flex-col gap-px p-1">
        {items.map((item) => (
          <li key={item.id}>
            <Row
              item={item}
              active={item.id === activeId}
              onOpen={onOpen}
              badge={badge}
              tooltip={tooltip}
            />
          </li>
        ))}
      </ul>
    </ScrollArea>
  )
}

import type {
  OpenHow,
  PaneMode,
  TabGroup,
  WorkspaceLayout,
  WorkspaceTab,
} from "./types"

const RECENT_LIMIT = 10
const CLOSED_LIMIT = 10

export type ClosedTab = { itemId: string; mode: PaneMode }
export type TabHistory = { back: (string | null)[]; forward: (string | null)[] }
export type FocusKind = "tab" | "pane" | "empty"

/** Layout plus the session-only state that never reaches storage. */
export type WorkspaceState = {
  layout: WorkspaceLayout
  closed: ClosedTab[]
  history: Record<string, TabHistory>
  focus?: { kind: FocusKind; nonce: number }
}

const newId = () => crypto.randomUUID()

function emptyTab(): WorkspaceTab {
  return { tabId: newId(), itemId: null, mode: "structured" }
}

export function freshLayout(): WorkspaceLayout {
  const tab = emptyTab()
  const groupId = newId()
  return {
    id: "layout",
    groups: [{ groupId, tabs: [tab], activeTabId: tab.tabId }],
    activeGroupId: groupId,
    sidebarOpen: true,
    recent: [],
  }
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null

const isTab = (value: unknown): value is WorkspaceTab =>
  isRecord(value) &&
  typeof value.tabId === "string" &&
  (value.itemId === null || typeof value.itemId === "string") &&
  (value.mode === "structured" || value.mode === "raw")

const isGroup = (value: unknown): value is TabGroup =>
  isRecord(value) &&
  typeof value.groupId === "string" &&
  typeof value.activeTabId === "string" &&
  Array.isArray(value.tabs) &&
  value.tabs.length > 0 &&
  value.tabs.every(isTab) &&
  value.tabs.some((t) => t.tabId === value.activeTabId)

/** Returns the stored layout when it is well formed, otherwise a fresh one-group layout. */
export function normalizeLayout(stored: unknown): WorkspaceLayout {
  const candidate = isRecord(stored) ? stored : undefined
  const groups = candidate?.groups
  if (
    !Array.isArray(groups) ||
    (groups.length !== 1 && groups.length !== 2) ||
    !groups.every(isGroup) ||
    !groups.some((g) => g.groupId === candidate?.activeGroupId)
  ) {
    return freshLayout()
  }
  return {
    id: "layout",
    groups,
    activeGroupId: candidate!.activeGroupId as string,
    sidebarOpen: candidate!.sidebarOpen !== false,
    recent: Array.isArray(candidate!.recent)
      ? candidate!.recent.filter((id): id is string => typeof id === "string")
      : [],
  }
}

export function initialState(layout: WorkspaceLayout): WorkspaceState {
  return { layout, closed: [], history: {} }
}

export function activeGroupOf(layout: WorkspaceLayout): TabGroup {
  return layout.groups.find((g) => g.groupId === layout.activeGroupId) ?? layout.groups[0]
}

export function activeTabOf(layout: WorkspaceLayout): WorkspaceTab {
  const group = activeGroupOf(layout)
  return group.tabs.find((t) => t.tabId === group.activeTabId) ?? group.tabs[0]
}

export function findTab(layout: WorkspaceLayout, tabId: string) {
  for (const group of layout.groups) {
    const tab = group.tabs.find((t) => t.tabId === tabId)
    if (tab) return { group, tab }
  }
  return undefined
}

function replaceGroup(layout: WorkspaceLayout, next: TabGroup): WorkspaceLayout {
  return { ...layout, groups: layout.groups.map((g) => (g.groupId === next.groupId ? next : g)) }
}

function withFocus(state: WorkspaceState, kind: FocusKind): WorkspaceState {
  return { ...state, focus: { kind, nonce: (state.focus?.nonce ?? 0) + 1 } }
}

function pushRecent(recent: string[], itemId: string | null): string[] {
  if (!itemId) return recent
  return [itemId, ...recent.filter((id) => id !== itemId)].slice(0, RECENT_LIMIT)
}

function insertTab(
  layout: WorkspaceLayout,
  group: TabGroup,
  tab: WorkspaceTab
): WorkspaceLayout {
  const at = group.tabs.findIndex((t) => t.tabId === group.activeTabId) + 1
  const tabs = [...group.tabs.slice(0, at), tab, ...group.tabs.slice(at)]
  return {
    ...replaceGroup(layout, { ...group, tabs, activeTabId: tab.tabId }),
    activeGroupId: group.groupId,
    recent: pushRecent(layout.recent, tab.itemId),
  }
}

/** Puts `tab` in a new group on the right, or in the other group when two already exist. */
function placeInSplit(layout: WorkspaceLayout, sourceGroupId: string, tab: WorkspaceTab): WorkspaceLayout {
  if (layout.groups.length === 1) {
    const group: TabGroup = { groupId: newId(), tabs: [tab], activeTabId: tab.tabId }
    return {
      ...layout,
      groups: [...layout.groups, group],
      activeGroupId: group.groupId,
      recent: pushRecent(layout.recent, tab.itemId),
    }
  }
  const other = layout.groups.find((g) => g.groupId !== sourceGroupId) ?? layout.groups[1]
  return insertTab(layout, other, tab)
}

function omitHistory(history: Record<string, TabHistory>, tabIds: string[]) {
  return Object.fromEntries(Object.entries(history).filter(([id]) => !tabIds.includes(id)))
}

export function newTab(state: WorkspaceState): WorkspaceState {
  const layout = insertTab(state.layout, activeGroupOf(state.layout), emptyTab())
  return withFocus({ ...state, layout }, "empty")
}

export function openItem(state: WorkspaceState, itemId: string, how: OpenHow): WorkspaceState {
  const { layout } = state
  if (how === "here") {
    const group = activeGroupOf(layout)
    const tab = activeTabOf(layout)
    if (tab.itemId === itemId) return withFocus(state, "pane")
    const tabs = group.tabs.map((t) => (t.tabId === tab.tabId ? { ...t, itemId } : t))
    const past = state.history[tab.tabId] ?? { back: [], forward: [] }
    return withFocus(
      {
        ...state,
        layout: {
          ...replaceGroup(layout, { ...group, tabs }),
          recent: pushRecent(layout.recent, itemId),
        },
        history: { ...state.history, [tab.tabId]: { back: [...past.back, tab.itemId], forward: [] } },
      },
      "pane"
    )
  }
  const mode = activeTabOf(layout).mode
  const tab: WorkspaceTab = { tabId: newId(), itemId, mode }
  if (how === "tab") {
    return withFocus({ ...state, layout: insertTab(layout, activeGroupOf(layout), tab) }, "pane")
  }
  return withFocus({ ...state, layout: placeInSplit(layout, layout.activeGroupId, tab) }, "pane")
}

export function split(state: WorkspaceState, tabId?: string): WorkspaceState {
  const { layout } = state
  const source = tabId
    ? findTab(layout, tabId)
    : { group: activeGroupOf(layout), tab: activeTabOf(layout) }
  if (!source) return state
  const copy: WorkspaceTab = { tabId: newId(), itemId: source.tab.itemId, mode: source.tab.mode }
  return withFocus({ ...state, layout: placeInSplit(layout, source.group.groupId, copy) }, "pane")
}

export function selectTab(state: WorkspaceState, tabId: string): WorkspaceState {
  const found = findTab(state.layout, tabId)
  if (!found) return state
  const { group } = found
  if (state.layout.activeGroupId === group.groupId && group.activeTabId === tabId) return state
  return withFocus(
    {
      ...state,
      layout: {
        ...replaceGroup(state.layout, { ...group, activeTabId: tabId }),
        activeGroupId: group.groupId,
      },
    },
    "tab"
  )
}

export function activateGroup(state: WorkspaceState, groupId: string): WorkspaceState {
  if (state.layout.activeGroupId === groupId) return state
  if (!state.layout.groups.some((g) => g.groupId === groupId)) return state
  return { ...state, layout: { ...state.layout, activeGroupId: groupId } }
}

export function closeTab(state: WorkspaceState, tabId: string): WorkspaceState {
  const found = findTab(state.layout, tabId)
  if (!found) return state
  const { group, tab } = found
  const { layout } = state
  const closed = tab.itemId
    ? [{ itemId: tab.itemId, mode: tab.mode }, ...state.closed].slice(0, CLOSED_LIMIT)
    : state.closed
  const history = omitHistory(state.history, [tabId])

  if (group.tabs.length === 1) {
    if (layout.groups.length === 2) {
      const remaining = layout.groups.find((g) => g.groupId !== group.groupId)!
      return withFocus(
        { ...state, layout: { ...layout, groups: [remaining], activeGroupId: remaining.groupId }, closed, history },
        "tab"
      )
    }
    if (tab.itemId === null) return state
    const fresh = emptyTab()
    return withFocus(
      { ...state, layout: replaceGroup(layout, { ...group, tabs: [fresh], activeTabId: fresh.tabId }), closed, history },
      "tab"
    )
  }

  const at = group.tabs.findIndex((t) => t.tabId === tabId)
  const tabs = group.tabs.filter((t) => t.tabId !== tabId)
  const activeTabId =
    group.activeTabId === tabId ? tabs[Math.min(at, tabs.length - 1)].tabId : group.activeTabId
  return withFocus(
    {
      ...state,
      layout: { ...replaceGroup(layout, { ...group, tabs, activeTabId }), activeGroupId: group.groupId },
      closed,
      history,
    },
    "tab"
  )
}

export function closeOthers(state: WorkspaceState, tabId: string): WorkspaceState {
  const found = findTab(state.layout, tabId)
  if (!found) return state
  const { group, tab } = found
  const dropped = group.tabs.filter((t) => t.tabId !== tabId)
  const closed = [
    ...dropped.flatMap((t) => (t.itemId ? [{ itemId: t.itemId, mode: t.mode }] : [])),
    ...state.closed,
  ].slice(0, CLOSED_LIMIT)
  const history = omitHistory(state.history, dropped.map((t) => t.tabId))
  return withFocus(
    {
      ...state,
      layout: {
        ...replaceGroup(state.layout, { ...group, tabs: [tab], activeTabId: tab.tabId }),
        activeGroupId: group.groupId,
      },
      closed,
      history,
    },
    "tab"
  )
}

export function reopenTab(state: WorkspaceState): WorkspaceState {
  const [last, ...closed] = state.closed
  if (!last) return state
  const tab: WorkspaceTab = { tabId: newId(), itemId: last.itemId, mode: last.mode }
  const layout = insertTab(state.layout, activeGroupOf(state.layout), tab)
  return withFocus({ ...state, layout, closed }, "pane")
}

export function setMode(state: WorkspaceState, tabId: string, mode: PaneMode): WorkspaceState {
  const found = findTab(state.layout, tabId)
  if (!found || found.tab.mode === mode) return state
  const tabs = found.group.tabs.map((t) => (t.tabId === tabId ? { ...t, mode } : t))
  return withFocus(
    { ...state, layout: replaceGroup(state.layout, { ...found.group, tabs }) },
    "pane"
  )
}

export function toggleSidebar(state: WorkspaceState): WorkspaceState {
  return { ...state, layout: { ...state.layout, sidebarOpen: !state.layout.sidebarOpen } }
}

export function navigate(state: WorkspaceState, tabId: string, direction: "back" | "forward"): WorkspaceState {
  const found = findTab(state.layout, tabId)
  const past = state.history[tabId]
  if (!found || !past) return state
  const from = direction === "back" ? past.back : past.forward
  if (from.length === 0) return state
  const target = from[from.length - 1]
  const rest = from.slice(0, -1)
  const pushed = [...(direction === "back" ? past.forward : past.back), found.tab.itemId]
  const history: TabHistory =
    direction === "back" ? { back: rest, forward: pushed } : { back: pushed, forward: rest }
  const tabs = found.group.tabs.map((t) => (t.tabId === tabId ? { ...t, itemId: target } : t))
  return withFocus(
    {
      ...state,
      layout: {
        ...replaceGroup(state.layout, { ...found.group, tabs }),
        recent: pushRecent(state.layout.recent, target),
      },
      history: { ...state.history, [tabId]: history },
    },
    "pane"
  )
}

