type PaneProps<T extends WorkspaceItem> = Omit<PaneHeaderProps, "title" | "hasItem"> & {
  item: T | undefined
  deleted: boolean
  empty: ReactNode
  maxContentWidth: number
  renderStructured: (item: T, api: { update: (patch: Partial<T>) => Promise<void> }) => ReactNode
  toRaw: (item: T) => string
  parseRaw: (raw: string, item: T) => T
  onChange: (next: T) => Promise<void>
}

function messageOf(cause: unknown): string {
  return cause instanceof Error ? cause.message : String(cause)
}

/**
 * Composes every write from the newest local record. The store publishes a
 * record only after its write resolves, so the `item` prop lags behind edits
 * already made; building a write from it alone would drop those edits.
 */
function createWriter<T extends WorkspaceItem>() {
  let prop: T | undefined
  let save: ((next: T) => Promise<void>) | undefined
  let unsettled: T | undefined
  let inflight = 0

  const latest = () => unsettled ?? prop

  function write(next: T): Promise<void> {
    if (!save) return Promise.resolve()
    unsettled = next
    inflight += 1
    return save(next).then(
      () => {
        inflight -= 1
      },
      (cause: unknown) => {
        inflight -= 1
        if (inflight === 0) unsettled = undefined
        throw cause
      }
    )
  }

  return {
    latest,
    write,
    update(patch: Partial<T>): Promise<void> {
      const base = latest()
      return base ? write({ ...base, ...patch }) : Promise.resolve()
    },
    saveWith(onChange: (next: T) => Promise<void>) {
      save = onChange
    },
    receive(item: T | undefined) {
      prop = item
      if (inflight === 0) unsettled = undefined
    },
  }
}

/** Header plus body for one tab: structured form, raw file, the empty pane, or the deleted notice. */
export function Pane<T extends WorkspaceItem>({
  item,
  deleted,
  empty,
  maxContentWidth,
  renderStructured,
  toRaw,
  parseRaw,
  onChange,
  ...header
}: PaneProps<T>) {
  const [rawError, setRawError] = useState<string>()
  const [writer] = useState(createWriter<T>)

  useEffect(() => {
    writer.saveWith(onChange)
  }, [writer, onChange])

  useEffect(() => {
    writer.receive(item)
  }, [writer, item])

  function commitRaw(raw: string) {
    const base = writer.latest()
    if (!base) return
    try {
      const next = parseRaw(raw, base)
      setRawError(undefined)
      writer.write(next).catch((cause: unknown) => setRawError(messageOf(cause)))
    } catch (cause) {
      setRawError(messageOf(cause))
    }
  }

  let body: ReactNode
  if (deleted) {
    body = (
      <EmptyState
        title="This item was deleted"
        action={
          <Button size="sm" variant="outline" onClick={header.onClose}>
            Close tab
          </Button>
        }
      />
    )
  } else if (!item) {
    body = empty
  } else if (header.mode === "raw") {
    body = <RawEditor value={toRaw(item)} error={rawError} onCommit={commitRaw} />
  } else {
    body = (
      <div className="mx-auto w-full p-4" style={{ maxWidth: maxContentWidth }}>
        {renderStructured(item, { update: (patch) => writer.update(patch) })}
      </div>
    )
  }

  return (
    <>
      <PaneHeader
        {...header}
        title={deleted ? "Deleted" : (item?.title ?? "New tab")}
        hasItem={!!item}
      />
      <div
        data-pane-body
        tabIndex={-1}
        className="min-h-0 flex-1 overflow-auto outline-none"
      >
        {body}
      </div>
    </>
  )
}

import { useEffect, useRef, useState } from "react"

import { Textarea } from "@/components/ui/textarea"

const IDLE_COMMIT_MS = 600

/**
 * Plain-text view of a record's file. Calls `onCommit` with the draft on blur
 * and after 600 ms idle; `error` is the message to show when the parent
 * rejected the last commit, and the draft is kept as typed until it is fixed.
 */
export function RawEditor({
  value,
  onCommit,
  error,
}: {
  value: string
  onCommit: (raw: string) => void
  error?: string
}) {
  const [draft, setDraft] = useState(value)
  const [seen, setSeen] = useState(value)
  const [committed, setCommitted] = useState(value)
  const timer = useRef<number | undefined>(undefined)
  const latest = useRef({ draft, committed, onCommit })

  useEffect(() => {
    latest.current = { draft, committed, onCommit }
  })

  if (value !== seen) {
    setSeen(value)
    if (!error && (draft === seen || draft === committed)) setDraft(value)
  }

  function commit(raw: string) {
    window.clearTimeout(timer.current)
    timer.current = undefined
    if (!error && (raw === value || raw === committed)) return
    setCommitted(raw)
    onCommit(raw)
  }

  useEffect(
    () => () => {
      if (timer.current === undefined) return
      window.clearTimeout(timer.current)
      const { draft: pending, committed: sent, onCommit: flush } = latest.current
      if (pending !== sent) flush(pending)
    },
    []
  )

  return (
    <div className="flex h-full min-h-0 flex-col">
      <Textarea
        data-raw-editor
        aria-label="Raw file"
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? "raw-editor-error" : undefined}
        spellCheck={false}
        value={draft}
        onChange={(event) => {
          const next = event.target.value
          setDraft(next)
          window.clearTimeout(timer.current)
          timer.current = window.setTimeout(() => commit(next), IDLE_COMMIT_MS)
        }}
        onBlur={() => commit(draft)}
        onKeyDown={(event) => {
          if (event.key !== "Escape") return
          event.preventDefault()
          event.currentTarget.closest<HTMLElement>("[data-pane-body]")?.focus()
        }}
        className="min-h-0 flex-1 resize-none rounded-none border-0 p-4 font-mono text-xs leading-relaxed shadow-none focus-visible:ring-0"
      />
      {error ? (
        <p id="raw-editor-error" role="alert" className="border-t bg-destructive/10 px-4 py-2 text-xs text-destructive">
          {error}
        </p>
      ) : null}
    </div>
  )
}

